mapper.select:
SELECT r.id, r.rating, r.content, r.status, r.admin_reply, r.create_time, u.username AS reviewerName, b.title AS bookTitle FROM book_review r LEFT JOIN sys_user u ON r.user_id = u.id LEFT JOIN book_info b ON r.book_id = b.id
AND r.rating = #{rating}
AND r.status = #{status}
ORDER BY r.create_time DESC
